void handle_vm_cmdGetClientAction(GameClient& cl, const uint8_t* body, size_t len)
{
    if (len < 2) return;
    uint16_t n = rd16be(body);
    if (n > 1023) n = 1023;
    if (2 + n > len) return;
    std::string s((const char*)body + 2, n);
    applyLpc("cmd_get_client_action", {make_int(cl.clientNo), make_string(s)});
}

